#!/bin/bash
# SC-158: the cast sheets and keyframes for the Mango Drink demo film, Qwen-Image 2.1 (bf16) on this Mac, one after
# another in the background. PNG originals land in src/img/ (gitignored); WebP copies and .prompt.json sidecars are
# written into ../img/ afterwards by sidecars.py. Log: src/gen-qwen.log.
set +u
PY="$HOME/qwen-image-bf16/.venv/bin/python"
GEN="$HOME/.claude/plugins/cache/qwen-bf16-local/qwen-image-bf16/0.2.0/server/qwen_image_bf16_mac.py"
HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/img"
S154="$HERE/../../SC-154/img"
PLANNER="$S154/cast-planner.webp"; KIRANA="$S154/cast-kirana.webp"
LAKSHMI="$OUT/cast-lakshmi.png"; MEERA="$OUT/cast-meera.png"; NEHA="$OUT/cast-neha.png"

NOTEXT="Photorealistic documentary photograph, 35 mm lens, natural light, realistic skin and fabric. No text, no logos, no lettering, no signs anywhere; every pack and carton unbranded."
PACKS="small upright yellow-orange tetra-pack cartons of mango drink with a ripe mango illustration and no readable words"
CARTONS="plain kraft cardboard cartons with a sage-green band"
SHEET="A character reference sheet on a plain neutral grey studio background, soft even light, photographic, realistic skin and fabric: the same person three times side by side, full face front view, three-quarter view and profile, head and shoulders, the same clothes in every view, no text, no labels, no logos. The person:"
NEW="Make one new photograph, not a reference sheet: the person from the reference sheet appears once, with exactly the same face, hair and clothes, in a real place."

gen() { # name seed aspect prompt [image...]
  local name="$1" seed="$2" aspect="$3" prompt="$4"; shift 4
  local args=()
  for im in "$@"; do args+=(--image "$im"); done
  [ -s "$OUT/$name.png" ] && { echo "skip $name"; return; }
  echo "== $name $(date +%H:%M:%S)"
  "$PY" "$GEN" "$prompt" --aspect "$aspect" --size 1024 --seed "$seed" --out "$OUT/$name.png" ${args[@]+"${args[@]}"} 2>&1 | grep -v "^$" | tail -3
}

# the three new people (Priya and the kirana owner reuse SC-154's sheets)
gen cast-lakshmi 158001 16:9 "$SHEET an Indian woman in her late forties who owns a distribution agency and its godown: black hair with grey streaks in a long plait over one shoulder, a deep teal cotton saree with a thin cream border and a cream blouse, a small gold nose pin, reading glasses hanging on a beaded cord round her neck, a plain steel watch; a composed, capable face with a slight smile"
gen cast-meera 158002 16:9 "$SHEET an Indian woman in her early thirties, a food bank's city lead: black hair in a high bun, a plain forest-green crew-neck T-shirt with no print, a navy lanyard with a blank white badge, a black digital watch; an energetic, kind face"
gen cast-neha 158003 16:9 "$SHEET an Indian woman in her late twenties, a software platform's operations lead: straight shoulder-length black hair, a plain white cotton shirt with the sleeves rolled to the elbow, small silver hoop earrings, thin black-framed glasses; a focused, friendly face"

# keyframes, in the film's order
gen k01-factory-dawn 158101 16:9 "A wide establishing shot at dawn of an Indian beverage factory's loading bay: a long concrete dock under a corrugated roof, pallets of $CARTONS, two blue trucks backed up to the dock, a supervisor in a yellow hi-vis vest with a clipboard, a worker pushing a pallet jack, mist and low warm sunlight raking across the yard from the right, a water tank on the roof, a tamarind tree beyond the wall. $NOTEXT"
gen k02-godown-lakshmi 158102 16:9 "$NEW A medium-wide shot inside a distributor's godown in Hyderabad's Begum Bazaar at mid-morning: tall wooden racks of $CARTONS on both sides, a shaft of sun from a high barred window, dust in the light. The woman in the teal saree stands in the aisle holding one open carton of $PACKS at chest height, reading glasses on, looking down at the date printed on its side with a worried, thoughtful expression. A hand truck behind her. $NOTEXT" "$LAKSHMI"
gen k03-priya-office 158123 16:9 "$NEW A medium shot of a bright modern office in Pune at 9 in the morning, the camera facing her across the desk: the woman in the navy pinstripe kurta with the lanyard sits at a white desk behind an open silver laptop whose plain silver lid faces the camera, so its screen is turned toward her and cannot be seen; her face is lit softly by the screen, one hand rests on the trackpad, a steel tumbler of chai beside the laptop, a potted money plant, large windows with soft morning light, blurred colleagues far behind. She looks at her screen, calm and attentive. $NOTEXT" "$PLANNER"
gen k04-neha-console 158104 16:9 "$NEW A medium shot of a software company's operations room in the evening: the woman in the white shirt and black-framed glasses sits side-on to the camera at a wide desk with a large monitor and a laptop, both showing a pale green operations dashboard with cards, a route of green dots and charts, no readable words; warm desk lamp, a wall of acoustic panels, a monstera plant, city lights blurred in the window. She has one hand on the mouse and looks at the monitor, focused. $NOTEXT" "$NEHA"
gen k05-priya-phone 158105 16:9 "$NEW A medium close-up in the same bright Pune office in the morning: the woman in the navy pinstripe kurta with the lanyard stands by the window holding a black smartphone in both hands at chest height, reading its screen with slightly raised eyebrows, the phone's screen a soft white glow with no readable words, a laptop and a chai tumbler on the desk behind her out of focus. $NOTEXT" "$PLANNER"
gen k06-lakshmi-label 158126 16:9 "$NEW A medium close-up inside the Begum Bazaar godown in warm morning light, the camera a little behind her shoulder: the woman in the teal saree holds her smartphone up with both hands toward the printed label on the side of a $CARTONS stacked on a rack at eye level, so the camera sees the back of the phone with its camera lenses, never its screen, which faces her; racks of cartons behind her, a bare bulb above. $NOTEXT" "$LAKSHMI"
gen k07-priya-approve 158107 16:9 "A close-up over the shoulder of an Indian woman's hands in a navy pinstripe kurta sleeve with a slim steel watch, holding a black smartphone at a white office desk, her right thumb about to tap a large rounded green button at the bottom of a white app screen that has a few pale grey lines and a big green number, no readable words; soft morning light from a window, a laptop blurred behind. $NOTEXT"
gen k08-kirana-phone 158108 16:9 "$NEW A medium shot of a small kirana shop in Hyderabad's old city at noon, seen from just outside the counter: the woman in the maroon saree with the mustard blouse stands behind a glass-fronted wooden counter reading her smartphone with a pleased smile, shelves packed with colourful unbranded packets, jars of sweets, hanging sachet strips, a weighing scale on the counter, a ceiling fan, bright sun on the lane outside. $NOTEXT" "$KIRANA"
gen k09-kirana-sale 158109 16:9 "$NEW A medium shot at the same kirana counter in the afternoon: the woman in the maroon saree with the mustard blouse hands a $PACKS across the counter to a young man in a grey shirt who holds out a coin, both smiling; a crate of the same yellow-orange tetra packs on the counter by the scale, shelves of colourful unbranded packets behind. $NOTEXT" "$KIRANA"
gen k10-staff-sale 158110 16:9 "$NEW A wide shot at violet dusk at a godown's gate in Hyderabad: a folding table at the gate under a sodium lamp, stacked with $PACKS, and the woman in the teal saree behind it handing a pack to the first of a short queue of godown workers in simple shirts and lungis, a small printed square code card propped on the table (a plain black-and-white pattern, no words), scooters parked along the wall, the sky amber at the horizon and deep violet above. $NOTEXT" "$LAKSHMI"
gen k11-foodbank-van 158111 16:9 "$NEW Two people from the reference sheets in one new photograph: a wide shot at the godown's loading door in late morning: a plain white delivery van with its rear doors open, the woman in the green T-shirt with the lanyard and bun passing a $CARTONS into it to a young volunteer in an orange vest inside the van, while the woman in the teal saree stands by the door holding a clipboard and watching with a warm smile; three more cartons on a hand truck beside them, a tamarind tree and a blue-washed wall. $NOTEXT" "$MEERA" "$LAKSHMI"
gen k12-van-round 158112 16:9 "A medium-wide shot on a Saturday morning in a narrow bazaar lane in Hyderabad's old city: a small white delivery van parked with its side door open, a young delivery worker in a blue shirt carrying a stack of two $CARTONS to a kirana shop's doorway where the shopkeeper waits, old painted shutters, strings of unbranded sachets, a cycle rickshaw passing, soft morning light down the lane. $NOTEXT"
gen k13-priya-papers 158133 16:9 "$NEW A medium shot in the bright Pune office in the afternoon, the camera facing her across the desk: the woman in the navy pinstripe kurta with the lanyard sits at her desk holding a tablet upright in her left hand with its screen toward her, so the camera sees only its thin edge and a plain dark back with no logo; beside her an open silver laptop turned toward her, its plain lid facing the camera, no screen visible; a stapled printout and a pen on the desk, a steel tumbler; she looks at the tablet with a small satisfied nod. $NOTEXT" "$PLANNER"
gen k14-office-dashboard 158114 16:9 "$NEW A medium shot in the Pune office at golden hour: the woman in the navy pinstripe kurta with the lanyard sits beside a slim Indian man in his mid-thirties in a charcoal polo shirt, both looking at a large monitor that shows a pale green dashboard with a rising line chart, stacked bars and a few cards, no readable words; she points at the chart with a pen, he nods, warm low light from the window across the desk. $NOTEXT" "$PLANNER"
gen k15-lane-golden 158135 16:9 "$NEW A wide shot at golden hour of a busy lane in Hyderabad's old city: the woman in the maroon saree with the mustard blouse (the only woman in a maroon saree in the picture) stands at the open door of her kirana shop holding one $PACKS out to her customer, a young man in his twenties in a pale blue checked shirt and jeans with a cloth shopping bag on his shoulder, who reaches for it and smiles; strings of unbranded sachets and jars at the door, scooters, a man carrying a sack, warm low sun flaring down the lane, the dome of an old gateway far behind. $NOTEXT" "$KIRANA"
gen k16-factory-line 158116 16:9 "A medium-wide shot inside a clean beverage packaging hall: a stainless-steel filling line carrying rows of $PACKS along a conveyor, a woman supervisor in a white coat, hairnet and safety glasses checking a pack with a tablet in her hand, soft white industrial light, stacked $CARTONS on a pallet at the end of the line. $NOTEXT"
echo "== done $(date +%H:%M:%S)"
